// A JSON schema check for the subset schemars writes (#269): deck-space's rig forms as schema.json (generated by
// deck/space/src/rig/tests.rs `rig_schema` – Rust stays the source of truth). Handles $ref (#/$defs/…), type (one or a
// list), properties / required / additionalProperties, items / minItems / maxItems, enum, const, oneOf, anyOf and
// `format: float` (serde reads an f32: a finite number within its range). Unknown keywords are ignored.

export type SchemaPath = (string | number)[];
export interface SchemaProblem {
	path: SchemaPath;
	message: string;
}
export type Schema = boolean | { [keyword: string]: unknown };
export interface SchemaRoot {
	$defs: Record<string, Schema>;
}

const F32_MAX = 3.4028234663852886e38;

function typeOf(v: unknown): string {
	if (v === null) return 'null';
	if (Array.isArray(v)) return 'array';
	if (typeof v === 'number') return Number.isInteger(v) ? 'integer' : 'number';
	return typeof v;
}

const fits = (v: unknown, type: string) => {
	const t = typeOf(v);
	return t === type || (type === 'number' && t === 'integer');
};

/** what a type list reads as in a message: "a number", "a list or null" */
function describe(types: string[]): string {
	const word: Record<string, string> = { object: 'an object', array: 'a list', string: 'a string', number: 'a number', integer: 'an integer', boolean: 'true or false', null: 'null' };
	return types.map((t) => word[t] ?? t).join(' or ');
}

const show = (path: SchemaPath) => (path.length ? path.map((p, i) => (typeof p === 'number' ? `[${p}]` : i ? `.${p}` : p)).join('') : 'the entry');

/** `value` against `schema` (a definition of `root`), every problem with its path */
export function checkSchema(root: SchemaRoot, schema: Schema, value: unknown, path: SchemaPath = []): SchemaProblem[] {
	if (schema === true) return [];
	if (schema === false) return [{ path, message: `${show(path)} is not allowed` }];
	const s = schema;
	if (typeof s.$ref === 'string') {
		const name = s.$ref.replace(/^#\/\$defs\//, '');
		const def = root.$defs[name];
		if (def === undefined) throw new Error(`schema: unknown $ref ${s.$ref}`);
		const out = checkSchema(root, def, value, path);
		// siblings of $ref (2020-12) are checked as well
		const { $ref: _ref, ...rest } = s;
		return Object.keys(rest).length ? [...out, ...checkSchema(root, rest, value, path)] : out;
	}
	if (Array.isArray(s.oneOf) || Array.isArray(s.anyOf)) {
		const options = (s.oneOf ?? s.anyOf) as Schema[];
		const results = options.map((o) => checkSchema(root, o, value, path));
		const ok = results.filter((r) => !r.length).length;
		if (s.oneOf ? ok === 1 : ok >= 1) return [];
		// enums written as oneOf of consts (schemars): one message with every allowed value
		if (options.every((o) => typeof o === 'object' && (Array.isArray(o.enum) || 'const' in o))) {
			const consts = options.flatMap((o) => (typeof o === 'object' ? (Array.isArray(o.enum) ? o.enum : [o.const]) : []));
			return [{ path, message: `${show(path)} must be one of ${consts.join(', ')}` }];
		}
		return results.sort((a, b) => a.length - b.length)[0] ?? [];
	}
	if (s.type !== undefined) {
		const types = (Array.isArray(s.type) ? s.type : [s.type]) as string[];
		if (!types.some((t) => fits(value, t))) return [{ path, message: `${show(path)} must be ${describe(types)}` }];
	}
	if ('const' in s && value !== s.const) return [{ path, message: `${show(path)} must be ${JSON.stringify(s.const)}` }];
	if (Array.isArray(s.enum) && !s.enum.includes(value)) return [{ path, message: `${show(path)} must be one of ${s.enum.join(', ')}` }];
	if (typeof value === 'number' && s.format === 'float' && !(Number.isFinite(value) && Math.abs(value) <= F32_MAX)) {
		return [{ path, message: `${show(path)} must be a number within an f32's range` }];
	}
	const out: SchemaProblem[] = [];
	if (Array.isArray(value)) {
		if (typeof s.minItems === 'number' && value.length < s.minItems) out.push({ path, message: `${show(path)} needs at least ${s.minItems} entries` });
		if (typeof s.maxItems === 'number' && value.length > s.maxItems) out.push({ path, message: `${show(path)} holds at most ${s.maxItems} entries` });
		if (s.items !== undefined) value.forEach((v, i) => out.push(...checkSchema(root, s.items as Schema, v, [...path, i])));
	} else if (value && typeof value === 'object') {
		const o = value as Record<string, unknown>;
		const props = (s.properties ?? {}) as Record<string, Schema>;
		for (const key of (s.required ?? []) as string[]) if (!(key in o)) out.push({ path: [...path, key], message: `${show([...path, key])} is required` });
		for (const [key, v] of Object.entries(o)) {
			if (key in props) out.push(...checkSchema(root, props[key], v, [...path, key]));
			else if (s.additionalProperties === false) out.push({ path: [...path, key], message: `unknown field "${key}"${path.length ? ` in ${show(path)}` : ''} (${Object.keys(props).join(', ')})` });
			else if (s.additionalProperties !== undefined && s.additionalProperties !== true) out.push(...checkSchema(root, s.additionalProperties as Schema, v, [...path, key]));
		}
	}
	return out;
}
